int ret;
long param_val = 0;

// Signature (int func, long *address)
int bdflush(int, long *);

// Start/Tune the daemon (func <= 0)
ret = bdflush(0, &param_val);

// Flush all dirty buffers (func = 1)
ret = bdflush(1, NULL);

// Read tuning parameter 2 (func = even >= 2)
long tune_read;
ret = bdflush(2, &tune_read);

// Set tuning parameter 3 (func = odd >= 3)
long new_ratio = 15;
ret = bdflush(3, &new_ratio);
